const KEY="keiba-note-records-v1";
let editId=null, periodMode="month", calendarDate=new Date(), supabaseClient=null, session=null, cloudReady=false;
const $=x=>document.getElementById(x);
function toNumber(v){if(typeof v==="number") return Number.isFinite(v)?v:0;if(v===null||v===undefined||v==="") return 0;const n=Number(String(v).replace(/,/g,""));return Number.isFinite(n)?n:0}
function normalizeRecord(r,i){return {id:r&&r.id!=null?String(r.id):String(Date.now()+i),date:typeof r?.date==="string"&&r.date?r.date.slice(0,10):"",course:typeof r?.course==="string"&&r.course?r.course:"その他",race:toNumber(r?.race),raceName:typeof r?.raceName==="string"?r.raceName.trim():"",raceCondition:typeof r?.raceCondition==="string"?r.raceCondition.trim():"",distance:typeof r?.distance==="string"?r.distance.trim():"",surface:typeof r?.surface==="string"?r.surface.trim():"",startTime:typeof r?.startTime==="string"?r.startTime.trim():"",raceKey:typeof r?.raceKey==="string"?r.raceKey.trim():"",meeting:typeof r?.meeting==="string"?r.meeting.trim():"",type:typeof r?.type==="string"&&r.type.trim()&&r.type!=="undefined"?r.type:"その他",horses:typeof r?.horses==="string"?r.horses.trim():"",inv:toNumber(r?.inv),ret:toNumber(r?.ret),memo:typeof r?.memo==="string"?r.memo:""}}
function loadLocal(){try{const raw=JSON.parse(localStorage.getItem(KEY)||"[]");const arr=Array.isArray(raw)?raw:[];const normalized=arr.map(normalizeRecord);localStorage.setItem(KEY,JSON.stringify(normalized));return normalized}catch(e){return []}}
let data=loadLocal();
const yen=x=>"¥"+Math.round(toNumber(x)).toLocaleString("ja-JP");
const sign=x=>{x=toNumber(x);return(x>=0?"+":"")+yen(x)};
const cls=x=>toNumber(x)>=0?"positive":"negative";
function saveLocal(){localStorage.setItem(KEY,JSON.stringify(data))}
function stats(a){const inv=a.reduce((s,r)=>s+toNumber(r.inv),0),ret=a.reduce((s,r)=>s+toNumber(r.ret),0),hit=a.filter(r=>toNumber(r.ret)>0).length;return{inv,ret,p:ret-inv,rate:inv?ret/inv*100:0,hitRate:a.length?hit/a.length*100:0,n:a.length}}
function render(){const s=stats(data);$("summary").innerHTML=`<div class="card"><span>累計収支</span><b class="${cls(s.p)}">${sign(s.p)}</b><small>投資 ${yen(s.inv)}</small></div><div class="card"><span>回収率</span><b>${s.rate.toFixed(1)}%</b></div><div class="card"><span>的中率</span><b>${s.hitRate.toFixed(1)}%</b></div><div class="card"><span>記録馬券</span><b>${s.n}</b></div>`;renderPeriod();renderBets();renderCourses();renderRecords();renderRanks();draw(false);renderCalendar()}
function renderPeriod(){const n=new Date();let title,arr;if(periodMode==="year"){const key=String(n.getFullYear());arr=data.filter(r=>r.date.startsWith(key));title=n.getFullYear()+"年の成績"}else{const key=n.getFullYear()+"-"+String(n.getMonth()+1).padStart(2,"0");arr=data.filter(r=>r.date.startsWith(key));title=n.getFullYear()+"年"+(n.getMonth()+1)+"月の成績"}const s=stats(arr);$("periodTitle").textContent=title;$("periodStats").innerHTML=[["投資額",yen(s.inv),""],["払戻額",yen(s.ret),""],["収支",sign(s.p),cls(s.p)],["回収率",s.rate.toFixed(1)+"%",""],["的中率",s.hitRate.toFixed(1)+"%",""],["記録馬券",s.n,""]].map(x=>`<div class="stat"><span>${x[0]}</span><b class="${x[2]}">${x[1]}</b></div>`).join("")}
function renderBets(){const types=[...new Set(data.map(r=>r.type||"その他"))];$("bets").innerHTML=types.length?types.map(t=>{const a=data.filter(r=>(r.type||"その他")===t),s=stats(a);return`<div class="bet"><h3>${t}</h3><p><span>投資</span><b>${yen(s.inv)}</b></p><p><span>払戻</span><b>${yen(s.ret)}</b></p><p><span>回収率</span><b>${s.rate.toFixed(1)}%</b></p><p><span>的中率</span><b>${s.hitRate.toFixed(1)}%</b></p><strong class="${cls(s.p)}">${sign(s.p)}</strong></div>`}).join(""):"<p class='muted'>データがありません。</p>"}
function renderCourses(){const courses=[...new Set(data.map(r=>r.course||"その他"))];$("courses").innerHTML=courses.length?courses.map(c=>{const a=data.filter(r=>(r.course||"その他")===c),s=stats(a);return`<div class="courseCard"><h3>${c}</h3><div><span>投資</span><b>${yen(s.inv)}</b></div><div><span>払戻</span><b>${yen(s.ret)}</b></div><div><span>収支</span><b class="${cls(s.p)}">${sign(s.p)}</b></div><div><span>回収率</span><b>${s.rate.toFixed(1)}%</b></div><div><span>的中率</span><b>${s.hitRate.toFixed(1)}%</b></div><small>${s.n}馬券</small></div>`}).join(""):"<p class='muted'>データがありません。</p>"}
function renderRanks(){const grouped=[...new Set(data.map(r=>r.type||"その他"))].map(t=>{const s=stats(data.filter(r=>(r.type||"その他")===t));return{t,...s}}).filter(x=>x.n);const ret=[...grouped].sort((a,b)=>b.rate-a.rate).slice(0,5),hit=[...grouped].sort((a,b)=>b.hitRate-a.hitRate).slice(0,5);const row=(x,i,key,suffix)=>`<div class="rank"><b>${i+1}</b><span>${x.t}</span><strong>${x[key].toFixed(1)}${suffix}</strong><small>${x.n}件</small></div>`;$("returnRank").innerHTML=ret.length?ret.map((x,i)=>row(x,i,"rate","%")).join(""):"<p class='muted'>データがありません。</p>";$("hitRank").innerHTML=hit.length?hit.map((x,i)=>row(x,i,"hitRate","%")).join(""):"<p class='muted'>データがありません。</p>"}
function renderRecords(){const el=$("records");el.innerHTML=data.length?[...data].sort((a,b)=>b.date.localeCompare(a.date)||String(b.id).localeCompare(String(a.id))).map(r=>{const p=toNumber(r.ret)-toNumber(r.inv);const horse=r.horses?` / 馬番 ${escapeHtml(r.horses)}`:"";const rn=r.raceName?` / ${escapeHtml(r.raceName)}`:"";return`<div class="record"><div class="muted">${r.date}</div><div><b>${escapeHtml(r.course)}${r.race}R　${escapeHtml(r.type)}</b><div class="muted">${rn}${horse||" / 馬番 未入力"} / ${escapeHtml(r.memo||"メモなし")} / 投資 ${yen(r.inv)} → 払戻 ${yen(r.ret)}</div><div class="actions"><button data-e="${r.id}">編集</button><button data-d="${r.id}">削除</button></div></div><b class="${cls(p)}">${sign(p)}</b></div>`}).join(""):"<p class='muted historyEmpty'>まだ収支データがありません。</p>"}
let chartAnimationId=0,chartRainbowPhase=0;
function draw(animateWhenVisible=false){const c=$("chart"),w=c.clientWidth||800,h=290,d=devicePixelRatio||1;c.width=w*d;c.height=h*d;const x=c.getContext("2d");x.setTransform(d,0,0,d,0,0);const n=+$('months').value,now=new Date(),ms=[];for(let i=n-1;i>=0;i--){const q=new Date(now.getFullYear(),now.getMonth()-i,1);ms.push(q.getFullYear()+"-"+String(q.getMonth()+1).padStart(2,"0"))}const v=ms.map(k=>data.filter(r=>r.date.startsWith(k)).reduce((s,r)=>s+toNumber(r.ret)-toNumber(r.inv),0));const rawMax=Math.max(...v,0),rawMin=Math.min(...v,0),rawRange=Math.max(rawMax-rawMin,1),pad=Math.max(rawRange*.16,1000),mx=rawMax+pad,mn=rawMin-pad,range=mx-mn,L=55,R=15,T=22,B=38,pw=w-L-R,ph=h-T-B,zero=T+(mx)/range*ph;const drawFrame=(progress=1)=>{x.clearRect(0,0,w,h);x.strokeStyle="#e5e7eb";x.fillStyle="#6b7280";x.font="12px sans-serif";x.textAlign="right";[mx,0,mn].forEach(q=>{const y=T+(mx-q)/range*ph;x.beginPath();x.moveTo(L,y);x.lineTo(w-R,y);x.stroke();x.fillText((q>=0?"+":"")+yen(q),L-7,y+4)});const gap=pw/n,bw=Math.max(7,gap*.5);x.textAlign="center";v.forEach((q,i)=>{const xx=L+gap*i+gap/2,target=T+(mx-q)/range*ph,y=zero+(target-zero)*progress;if(q>0){const g=x.createLinearGradient(xx-bw/2,Math.min(y,zero),xx+bw/2,Math.max(y,zero));for(let k=0;k<=12;k++){const hue=(chartRainbowPhase*70+k*30+i*18)%360;g.addColorStop(k/12,`hsl(${hue} 85% 52%)`)}x.fillStyle=g;x.fillRect(xx-bw/2,Math.min(y,zero),bw,Math.abs(y-zero))}else if(q<0){x.fillStyle="#dc2626";x.fillRect(xx-bw/2,Math.min(y,zero),bw,Math.abs(y-zero))}x.fillStyle="#6b7280";x.fillText(ms[i].slice(5).replace("-","/"),xx,h-14)})};cancelAnimationFrame(chartAnimationId);if(!animateWhenVisible){drawFrame(1);return}const startTime=performance.now(),duration=650;const animate=(nowTime)=>{const p=Math.min(1,(nowTime-startTime)/duration),ease=1-Math.pow(1-p,3);chartRainbowPhase=nowTime/1000;drawFrame(ease);chartAnimationId=requestAnimationFrame(animate)};chartAnimationId=requestAnimationFrame(animate)}
async function loadRaceDates(){if(scheduleDatePromise)return scheduleDatePromise;scheduleDatePromise=(async()=>{try{const url=new URL("./data/jra-schedule.json",document.baseURI);url.searchParams.set("calendar",Date.now());const res=await fetch(url,{cache:"no-store"});if(!res.ok)throw new Error("schedule fetch failed");const obj=await res.json();const rows=Array.isArray(obj)?obj:(Array.isArray(obj?.races)?obj.races:[]);const dates=new Set();rows.forEach(r=>{const d=String(r.date||"").slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(d))dates.add(d)});window.KEIBA_RACE_DATES=dates;renderCalendar()}catch(e){window.KEIBA_RACE_DATES=new Set()}})();return scheduleDatePromise}
function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth();$("calendarTitle").textContent=y+"年"+(m+1)+"月";const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),daily={};data.forEach(r=>{if(r.date.startsWith(y+"-"+String(m+1).padStart(2,"0"))){const d=Number(r.date.slice(8,10));(daily[d]||(daily[d]=[])).push(r)} });let html=["日","月","火","水","木","金","土"].map(x=>`<div class="calHead">${x}</div>`).join("");for(let i=0;i<first;i++)html+='<div class="day empty"></div>';for(let d=1;d<=days;d++){const rows=daily[d]||[],p=rows.reduce((s,r)=>s+toNumber(r.ret)-toNumber(r.inv),0);const dateKey=`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;const has=rows.length?" hasData":"";const raceDay=window.KEIBA_RACE_DATES.has(dateKey)?" raceDay":"";html+=`<div class="day ${p>0?'up':p<0?'down':''}${has}${raceDay}" data-date="${dateKey}" ${rows.length?'tabindex="0" role="button"':''}><span>${d}</span>${rows.length?`<b>${p>=0?"+":""}${Math.round(p).toLocaleString("ja-JP")}</b>`:""}</div>`}$("calendar").innerHTML=html}
function openHistory(){renderRecords();$("historyModal").classList.remove("hide")}
function closeHistory(){$("historyModal").classList.add("hide")}
function openCalendarDetail(date){const rows=[...data].filter(r=>r.date===date).sort((a,b)=>String(a.id).localeCompare(String(b.id)));const total=rows.reduce((s,r)=>s+toNumber(r.ret)-toNumber(r.inv),0);$("calendarDetailTitle").textContent=date.replace(/^(\d{4})-(\d{2})-(\d{2})$/,"$1年$2月$3日")+"の内訳";$("calendarDetail").innerHTML=rows.length?`<div class="calendarDetailList">${rows.map(r=>{const p=toNumber(r.ret)-toNumber(r.inv);const rn=r.raceName?` / ${escapeHtml(r.raceName)}`:"";const horse=r.horses?` / 馬番 ${escapeHtml(r.horses)}`:"";return`<div class="calendarDetailItem"><div class="calendarDetailItemTop"><b>${escapeHtml(r.course)}${r.race}R　${escapeHtml(r.type)}</b><b class="${cls(p)}">${sign(p)}</b></div><div class="detailMeta">${rn}${horse||" / 馬番 未入力"}<br>投資 ${yen(r.inv)} → 払戻 ${yen(r.ret)}<br>${escapeHtml(r.memo||"メモなし")}</div></div>`}).join("")}</div><div class="detailSummary"><b>この日の合計：<span class="${cls(total)}">${sign(total)}</span></b></div>`:"<p class='muted'>この日の収支記録はありません。</p>";$("calendarDetailModal").classList.remove("hide")}
function closeCalendarDetail(){$("calendarDetailModal").classList.add("hide")}
// V5.4.14: race schedule is read only from the repository-hosted JSON.
// The app never contacts JRA or a free proxy from the browser. This keeps
// GitHub Pages/iPhone operation independent of external access restrictions.
window.KEIBA_SCHEDULE=[];window.KEIBA_SELECTED_RACE=null;window.KEIBA_RACE_DATES=new Set();let scheduleDatePromise=null;
function jraDayUrl(date){const [y,m,d]=date.split("-");return `https://www.jra.go.jp/keiba/calendar${y}/${y}/${Number(m)}/${m}${d}.html`}
function setScheduleCourseOptions(items,selected=""){const el=$("course");el.innerHTML=`<option value="">${items.length?"競馬場を選択":"この日の開催データがありません"}</option>`+items.map(x=>`<option value="${escapeHtml(x.course)}">${escapeHtml(x.course)}${x.meeting?`（${escapeHtml(x.meeting)}）`:""}</option>`).join("");el.value=selected||"";el.disabled=!items.length&&!selected}
function resetRaceSelect(){const el=$("race");el.innerHTML='<option value="">競馬場を選択してください</option>';el.disabled=true;$("raceMeta").classList.add("hide");window.KEIBA_SELECTED_RACE=null}
function setRaceOptions(items,selected=""){const el=$("race");el.innerHTML=`<option value="">${items.length?"レースを選択":"レース情報がありません"}</option>`+items.map(x=>{const label=`${x.race}R　${x.raceName||"レース"}${x.distance?`　${x.distance}`:""}${x.surface?` ${x.surface}`:""}${x.startTime?`　${x.startTime}`:""}`;return`<option value="${x.race}">${escapeHtml(label)}</option>`}).join("");el.disabled=!items.length;el.value=selected?String(selected):""}
function showRaceMeta(r){const meta=$("raceMeta");if(!r||!r.race)return meta.classList.add("hide");meta.classList.remove("hide");meta.innerHTML=`<b>${escapeHtml(r.raceName||`${r.race}R`)}</b>${r.raceCondition&&r.raceCondition!==r.raceName?`<span>${escapeHtml(r.raceCondition)}</span>`:""}${r.meeting?`<span>${escapeHtml(r.meeting)}</span>`:""}${r.startTime?`<span>発走 ${escapeHtml(r.startTime)}</span>`:""}<a href="${escapeHtml(jraDayUrl($("date").value))}" target="_blank" rel="noopener">JRA公式番組を見る</a>`}
async function loadBundledSchedule(date){
  try{
    const url=new URL("./data/jra-schedule.json",document.baseURI);url.searchParams.set("v",date);
    const res=await fetch(url.href,{cache:"no-store"});
    if(!res.ok)throw Error(`HTTP ${res.status}`);
    const json=await res.json();
    const races=Array.isArray(json.races)?json.races.filter(r=>r&&r.date===date):[];
    window.KEIBA_SCHEDULE=races;
    const courses=[...new Map(races.map(r=>[r.course,{course:r.course,meeting:r.meeting||""}])).values()];
    setScheduleCourseOptions(courses);
    resetRaceSelect();
    if(courses.length){
      $("scheduleStatus").textContent=`${courses.length}場を表示（保存済みデータ）`;
      $("scheduleStatus").className="scheduleStatus muted";
      $("raceStatus").textContent="競馬場を選ぶとレース名を表示します。";
      return true;
    }
    $("scheduleStatus").textContent="この日の開催データはまだ登録されていません。";
    $("scheduleStatus").className="scheduleStatus muted";
    $("raceStatus").textContent="JRA公式番組ページで最新情報を確認できます。";
    return false;
  }catch(e){
    console.warn("Bundled JRA schedule unavailable",e);
    window.KEIBA_SCHEDULE=[];
    setScheduleCourseOptions([]);resetRaceSelect();
    $("scheduleStatus").textContent="保存済みの開催データを読み込めませんでした。";
    return false;
  }
}
function formatScheduleUpdatedAt(value){
  if(!value)return "未取得";
  const d=new Date(value);
  if(Number.isNaN(d.getTime()))return "日時不明";
  return new Intl.DateTimeFormat("ja-JP",{timeZone:"Asia/Tokyo",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}).format(d);
}
function renderScheduleMonitor(json){
  const badge=$("scheduleUpdateBadge"),updated=$("scheduleUpdatedAt"),count=$("scheduleRaceCount"),range=$("scheduleDateRange"),note=$("scheduleMonitorNote");
  if(!badge||!updated||!count||!range||!note)return;
  const races=Array.isArray(json?.races)?json.races.filter(r=>r&&r.date):[];
  const dates=[...new Set(races.map(r=>r.date))].sort();
  updated.textContent=formatScheduleUpdatedAt(json?.updatedAt);
  count.textContent=`${races.length.toLocaleString("ja-JP")}レース`;
  range.textContent=dates.length?`${dates[0]} ～ ${dates[dates.length-1]}`:"データなし";
  const t=json?.updatedAt?new Date(json.updatedAt).getTime():NaN;
  const ageHours=Number.isFinite(t)?Math.max(0,(Date.now()-t)/3600000):Infinity;
  badge.className="scheduleUpdateBadge";
  if(!races.length||!Number.isFinite(t)){
    badge.textContent="⚠ 要確認";badge.classList.add("warn");
    note.textContent="レース情報を確認できませんでした。GitHub Actionsの自動更新状況を確認してください。";
  }else if(ageHours<=48){
    badge.textContent="● 自動更新：正常";badge.classList.add("ok");
    note.textContent="最新のレース情報ファイルを読み込んでいます。通常はGitHubでの手動更新は不要です。";
  }else if(ageHours<=72){
    badge.textContent="△ 更新を確認";badge.classList.add("warn");
    note.textContent="最終更新から時間が経過しています。JRAの番組公開状況とGitHub Actionsを確認してください。";
  }else{
    badge.textContent="⚠ データが古い可能性";badge.classList.add("stale");
    note.textContent="最終更新から72時間を超えています。GitHub Actionsの実行結果を確認してください。";
  }
}
async function loadScheduleMonitor(){
  try{
    const url=new URL("./data/jra-schedule.json",document.baseURI);url.searchParams.set("monitor",Date.now());
    const res=await fetch(url.href,{cache:"no-store"});
    if(!res.ok)throw Error(`HTTP ${res.status}`);
    const json=await res.json();
    renderScheduleMonitor(json);
  }catch(e){
    renderScheduleMonitor(null);
    console.warn("Schedule monitor unavailable",e);
  }
}

async function loadJraSchedule(date){
  if(!date)return;
  $("scheduleStatus").textContent="保存済み開催情報を読み込み中…";
  $("scheduleStatus").className="scheduleStatus muted";
  resetRaceSelect();window.KEIBA_SCHEDULE=[];
  await loadBundledSchedule(date);
}

function openScheduleMonitor(){
  const modal=$("scheduleMonitorModal");
  if(!modal)return;
  modal.classList.remove("hide");
  loadScheduleMonitor();
}
function closeScheduleMonitor(){
  const modal=$("scheduleMonitorModal");
  if(modal)modal.classList.add("hide");
}
const scheduleMonitorLink=$("menuScheduleMonitorLink");
if(scheduleMonitorLink)scheduleMonitorLink.addEventListener("click",e=>{
  e.preventDefault();
  $("sideMenu")?.classList.remove("open");
  $("menuBackdrop")?.classList.remove("open");
  openScheduleMonitor();
});
$("closeScheduleMonitor")?.addEventListener("click",closeScheduleMonitor);
$("scheduleMonitorModal")?.addEventListener("click",e=>{
  if(e.target.id==="scheduleMonitorModal")closeScheduleMonitor();
});
document.addEventListener("keydown",e=>{
  if(e.key==="Escape")closeScheduleMonitor();
});

$("date").addEventListener("change",()=>loadJraSchedule($("date").value));$("course").addEventListener("change",()=>{const c=$("course").value;const races=window.KEIBA_SCHEDULE.filter(x=>x.course===c);setRaceOptions(races);$("raceStatus").textContent=races.length?`${races.length}レースを表示しています。`:"レース情報がありません。"});$("race").addEventListener("change",()=>{const r=window.KEIBA_SCHEDULE.find(x=>x.course===$("course").value&&String(x.race)===$("race").value);window.KEIBA_SELECTED_RACE=r||null;showRaceMeta(r)});

function makeBetRow(r={}){const wrap=document.createElement("div");wrap.className="betRow";wrap.innerHTML=`<div class="betRowHead"><b>馬券</b><button type="button" class="removeBetRow">削除</button></div><div class="betRowGrid"><label>馬券種<select class="bet-type"><option>複勝</option><option>ワイド</option><option>単勝</option><option>馬連</option><option>馬単</option><option>三連複</option><option>三連単</option><option>その他</option></select></label><label>馬番<div class="horseInputWrap"><input class="bet-horses" type="text" inputmode="numeric" autocomplete="off" pattern="[0-9\- ]*" placeholder="例：8 / 5-8 / 1-3-7"><button type="button" class="horseHyphen" aria-label="ハイフンを入力">−</button></div></label><label>購入金額<input class="bet-inv" type="number" inputmode="numeric" min="0" step="100" required></label><label>払戻金額<input class="bet-ret" type="number" inputmode="numeric" min="0" step="10" required></label><label class="full">メモ<input class="bet-memo" maxlength="100" placeholder="例：複勝500円"></label></div>`;wrap.querySelector(".bet-type").value=r.type||"複勝";wrap.querySelector(".bet-horses").value=r.horses||"";wrap.querySelector(".bet-inv").value=r.inv??"";wrap.querySelector(".bet-ret").value=r.ret??"";wrap.querySelector(".bet-memo").value=r.memo||"";wrap.querySelector(".horseHyphen").onclick=()=>{const input=wrap.querySelector(".bet-horses");const start=input.selectionStart??input.value.length;const end=input.selectionEnd??start;input.value=input.value.slice(0,start)+"-"+input.value.slice(end);input.focus();input.setSelectionRange(start+1,start+1);};wrap.querySelector(".removeBetRow").onclick=()=>{if($("betRows").children.length>1)wrap.remove()};$("betRows").appendChild(wrap)}
function resetBetRows(){$("betRows").innerHTML="";makeBetRow()}
function open(r=null){editId=r?r.id:null;$("mtitle").textContent=r?"収支を編集":"収支を記録";$("save").textContent=r?"変更を保存":"まとめて記録する";$("date").value=r?r.date:new Date().toISOString().slice(0,10);resetBetRows();if(r){setScheduleCourseOptions([{course:r.course,meeting:r.meeting||""}],r.course);setRaceOptions([{race:r.race,raceName:r.raceName||"",raceCondition:r.raceCondition||"",distance:r.distance||"",surface:r.surface||"",startTime:r.startTime||"",raceKey:r.raceKey||"",meeting:r.meeting||""}],r.race);showRaceMeta(r)}else{setScheduleCourseOptions([]);resetRaceSelect()}if(r){const row=$("betRows").firstElementChild;row.querySelector(".bet-type").value=r.type;row.querySelector(".bet-horses").value=r.horses;row.querySelector(".bet-inv").value=r.inv;row.querySelector(".bet-ret").value=r.ret;row.querySelector(".bet-memo").value=r.memo}$("modal").classList.remove("hide");setTimeout(()=>$("date").focus({preventScroll:true}),50);if(!r)loadJraSchedule($("date").value)}
function close(){ $("modal").classList.add("hide");$("form").reset();$("betRows").innerHTML="";editId=null;setTimeout(()=>window.scrollTo({top:window.scrollY,behavior:"auto"}),0)}
function setStatus(text,kind=""){const el=$("syncStatus");el.textContent=text;el.className="syncStatus "+kind}
function cloudConfigured(){return window.KEIBA_CONFIG&&window.KEIBA_CONFIG.supabaseUrl&&window.KEIBA_CONFIG.supabaseKey&&!window.KEIBA_CONFIG.supabaseUrl.includes("YOUR_")&&!window.KEIBA_CONFIG.supabaseKey.includes("YOUR_")}
async function initCloud(){if(!cloudConfigured()){setStatus("Supabase未設定","warn");$("authMessage").textContent="まずSupabaseプロジェクトを作成し、config.jsにURLとPublishable keyを設定してください。現在は端末内保存で動作します。";return}try{supabaseClient=window.supabase.createClient(window.KEIBA_CONFIG.supabaseUrl,window.KEIBA_CONFIG.supabaseKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const res=await supabaseClient.auth.getSession();session=res.data.session;await updateAuthUI();if(session)await initialCloudSync();supabaseClient.auth.onAuthStateChange(async(_event,s)=>{session=s;await updateAuthUI();if(s&&_event!=="INITIAL_SESSION")await initialCloudSync()})}catch(e){setStatus("接続エラー","error");$("authMessage").textContent="Supabaseの設定を確認してください。";console.error(e)}}
async function updateAuthUI(){const area=$("accountArea"),box=$("authBox");if(session){area.innerHTML=`<div class="account"><span>${escapeHtml(session.user.email||"")}</span><button id="signOut">ログアウト</button></div>`;box.classList.add("hide");$("authMessage").textContent="クラウド同期中。PC・iPhoneで同じアカウントにログインしてください。";setStatus("クラウド同期中","ok");$("signOut").onclick=async()=>{await supabaseClient.auth.signOut()}}else{area.innerHTML="";box.classList.remove("hide");if(cloudConfigured()){setStatus("未ログイン","warn");$("authMessage").textContent="ログインするとクラウド同期が有効になります。"}}
}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
async function signIn(){if(!supabaseClient)return alert("Supabaseの設定がまだ完了していません。");const email=$("email").value.trim(),password=$("password").value;if(!email||!password)return alert("メールアドレスとパスワードを入力してください。");const{error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)alert("ログインできませんでした。\n"+error.message)}
async function signUp(){if(!supabaseClient)return alert("Supabaseの設定がまだ完了していません。");const email=$("email").value.trim(),password=$("password").value;if(!email||password.length<6)return alert("メールアドレスと6文字以上のパスワードを入力してください。");const{error}=await supabaseClient.auth.signUp({email,password});if(error)alert("登録できませんでした。\n"+error.message);else alert("登録処理を開始しました。メール確認が有効な場合は、届いたメールを確認してください。")}
function cloudRow(r,userId){return{user_id:userId,id:String(r.id),date:r.date||"1970-01-01",course:r.course||"その他",race:Math.round(toNumber(r.race)),race_name:r.raceName||"",race_condition:r.raceCondition||"",distance:r.distance||"",surface:r.surface||"",start_time:r.startTime||"",race_key:r.raceKey||"",meeting:r.meeting||"",type:r.type||"その他",horses:r.horses||"",inv:toNumber(r.inv),ret:toNumber(r.ret),memo:r.memo||"",updated_at:new Date().toISOString()}}
function fromCloud(r){return normalizeRecord({id:r.id,date:r.date,course:r.course,race:r.race,raceName:r.race_name,raceCondition:r.race_condition,distance:r.distance,surface:r.surface,startTime:r.start_time,raceKey:r.race_key,meeting:r.meeting,type:r.type,horses:r.horses,inv:r.inv,ret:r.ret,memo:r.memo},0)}
function predictionCloudRow(p,userId){return{user_id:userId,id:String(p.id),date:p.date||"1970-01-01",course:p.course||"その他",race:Math.round(toNumber(p.race)),main:p.main||"",second:p.second||"",third:p.third||"",fukusho:p.fukusho||"",wide:p.wide||"",confidence:toNumber(p.confidence),comment:p.comment||"",result:p.result||"",result_data:p.resultData||{},fukusho_hit:!!p.fukushoHit,wide_hit:!!p.wideHit,result_entered:!!p.resultEntered,updated_at:new Date().toISOString()}}
function predictionFromCloud(r){return normalizePrediction({id:r.id,date:r.date,course:r.course,race:r.race,main:r.main,second:r.second,third:r.third,fukusho:r.fukusho,wide:r.wide,confidence:r.confidence,comment:r.comment,result:r.result,resultData:r.result_data,fukushoHit:r.fukusho_hit,wideHit:r.wide_hit,resultEntered:r.result_entered},0)}
async function syncPredictions(){if(!session||!supabaseClient)return;const{data:rows,error}=await supabaseClient.from("keiba_predictions").select("*").eq("user_id",session.user.id);if(error)throw error;const cloud=(rows||[]).map(predictionFromCloud);if(cloud.length===0&&predictions.length){const{error:e}=await supabaseClient.from("keiba_predictions").upsert(predictions.map(p=>predictionCloudRow(p,session.user.id)),{onConflict:"user_id,id"});if(e)throw e}else if(cloud.length){const ids=new Set(cloud.map(p=>p.id));const missing=predictions.filter(p=>!ids.has(p.id));if(missing.length){const{error:e}=await supabaseClient.from("keiba_predictions").upsert(missing.map(p=>predictionCloudRow(p,session.user.id)),{onConflict:"user_id,id"});if(e)throw e;cloud.push(...missing)}predictions=cloud;savePredictions();renderAi()}await applyJraResults(true)}
async function upsertPredictionCloud(p){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_predictions").upsert(predictionCloudRow(p,session.user.id),{onConflict:"user_id,id"});if(error){console.error(error);setStatus("同期エラー","error");alert("AI予想のクラウド保存に失敗しました。端末には保存されています。\n"+error.message)}else setStatus("同期済み","ok")}
async function deletePredictionCloud(id){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_predictions").delete().eq("user_id",session.user.id).eq("id",String(id));if(error){console.error(error);setStatus("同期エラー","error")}}
async function initialCloudSync(){if(!session||!supabaseClient)return;try{setStatus("同期中…","sync");const{data:rows,error}=await supabaseClient.from("keiba_records").select("*").eq("user_id",session.user.id);if(error)throw error;const cloud=(rows||[]).map(fromCloud);if(cloud.length===0&&data.length>0){const ok=confirm(`この端末には${data.length}件のV4データがあります。クラウドへ移行しますか？\n\n「OK」→既存データをクラウドへ保存\n「キャンセル」→クラウドは空のまま`);if(ok){const payload=data.map(r=>cloudRow(r,session.user.id));const{error:e}=await supabaseClient.from("keiba_records").upsert(payload,{onConflict:"user_id,id"});if(e)throw e;setStatus("同期済み","ok");await syncPredictions();return}}else if(cloud.length>0){const cloudIds=new Set(cloud.map(r=>String(r.id)));const missing=data.filter(r=>!cloudIds.has(String(r.id)));if(missing.length){const{error:e}=await supabaseClient.from("keiba_records").upsert(missing.map(r=>cloudRow(r,session.user.id)),{onConflict:"user_id,id"});if(e)throw e;cloud.push(...missing.map(normalizeRecord))}data=cloud;saveLocal();render()}await syncPredictions();setStatus("同期済み","ok")}catch(e){console.error(e);setStatus("同期エラー","error");$("authMessage").textContent="クラウド同期に失敗しました。端末内データは保持しています。";}}
async function upsertCloud(r){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_records").upsert(cloudRow(r,session.user.id),{onConflict:"user_id,id"});if(error){console.error(error);setStatus("同期エラー","error");alert("クラウド保存に失敗しました。端末内には保存されています。\n"+error.message)}else setStatus("同期済み","ok")}
async function deleteCloud(id){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_records").delete().eq("user_id",session.user.id).eq("id",String(id));if(error){console.error(error);setStatus("同期エラー","error");alert("クラウド削除に失敗しました。\n"+error.message)}}
async function clearCloud(){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_records").delete().eq("user_id",session.user.id);if(error){console.error(error);setStatus("同期エラー","error");alert("クラウド削除に失敗しました。\n"+error.message)}}
async function submitRecords(e){e.preventDefault();const date=$("date").value,course=$("course").value,race=toNumber($("race").value);if(!date||!course||!race)return alert("日付・競馬場・レースを入力してください。");const selected=(window.KEIBA_SCHEDULE||[]).find(x=>x.course===course&&toNumber(x.race)===race)||window.KEIBA_SELECTED_RACE||{};const rows=[...$("betRows").querySelectorAll(".betRow")];if(!rows.length)return alert("馬券を1件以上追加してください。");const base={date,course,race,raceName:selected.raceName||"",raceCondition:selected.raceCondition||"",distance:selected.distance||"",surface:selected.surface||"",startTime:selected.startTime||"",raceKey:selected.raceKey||`${date}-${course}-${race}`,meeting:selected.meeting||""};const records=rows.map((row,i)=>normalizeRecord({id:editId&&i===0?editId:String(Date.now())+"-"+i,...base,type:row.querySelector(".bet-type").value,horses:row.querySelector(".bet-horses").value,memo:row.querySelector(".bet-memo").value.trim(),inv:row.querySelector(".bet-inv").value,ret:row.querySelector(".bet-ret").value},i));if(editId){const idx=data.findIndex(x=>String(x.id)===String(editId));if(idx>=0)data[idx]=records[0];else data.push(records[0]);for(let i=1;i<records.length;i++)data.push(records[i])}else data.push(...records);saveLocal();render();close();for(const r of records)await upsertCloud(r)}
