$("records").onclick=async e=>{const b=e.target.closest("button");if(!b)return;const id=b.dataset.e||b.dataset.d;if(b.dataset.e){const r=data.find(x=>String(x.id)===String(id));if(r){closeHistory();open(r)}}else if(confirm("この記録を削除しますか？")){data=data.filter(x=>String(x.id)!==String(id));saveLocal();render();await deleteCloud(id)}};
