$("importData").onclick=()=>$("fileInput").click();$("fileInput").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const arr=JSON.parse(await f.text());if(!Array.isArray(arr))throw Error("配列ではありません");const imported=arr.map(normalizeRecord);if(!confirm(`${imported.length}件を復元します。現在のデータに追加・上書きしますか？`))return;const map=new Map(data.map(r=>[String(r.id),r]));imported.forEach(r=>map.set(String(r.id),r));data=[...map.values()];saveLocal();render();if(session&&supabaseClient){const{error}=await supabaseClient.from("keiba_records").upsert(data.map(r=>cloudRow(r,session.user.id)),{onConflict:"user_id,id"});if(error)throw error;setStatus("同期済み","ok")}alert("バックアップを復元しました。") }catch(err){alert("復元できませんでした。JSONバックアップを確認してください。\n"+err.message)}finally{e.target.value=""}};
const PKEY="keiba-note-predictions-v2";
let predictions=[];
let jraResults=[];
let jraResultsUpdatedAt="";
function loadPredictions(){try{const a=JSON.parse(localStorage.getItem(PKEY)||localStorage.getItem("keiba-note-predictions-v1")||"[]");return Array.isArray(a)?a.map(normalizePrediction):[]}catch(e){return []}}
function normalizePrediction(p,i){return{id:p&&p.id!=null?String(p.id):"p"+Date.now()+i,raceKey:String(p?.raceKey||resultKey(p?.date||"",p?.course||"",p?.race||0)),date:String(p?.date||"").slice(0,10),course:String(p?.course||"その他"),race:toNumber(p?.race),raceName:String(p?.raceName||""),raceCondition:String(p?.raceCondition||""),distance:String(p?.distance||""),surface:String(p?.surface||""),fieldSize:toNumber(p?.fieldSize),going:String(p?.going||""),main:String(p?.main||""),second:String(p?.second||""),third:String(p?.third||""),fourth:String(p?.fourth||""),fifth:String(p?.fifth||""),confidence:Math.max(0,Math.min(100,toNumber(p?.confidence))),status:["BUY","HOLD","SKIP"].includes(p?.status)?p.status:"HOLD",comment:String(p?.comment||""),predictionTime:String(p?.predictionTime||new Date().toISOString()),marketSnapshot:p?.marketSnapshot&&typeof p.marketSnapshot==="object"?p.marketSnapshot:{winOdds:String(p?.winOdds||""),placeOdds:String(p?.placeOdds||""),wideOdds:String(p?.wideOdds||""),weight:String(p?.weight||""),weightChange:String(p?.weightChange||""),going:String(p?.going||"")},horseEvaluations:p?.horseEvaluations&&typeof p.horseEvaluations==="object"?p.horseEvaluations:{},resultEntered:false}}
function savePredictions(){localStorage.setItem(PKEY,JSON.stringify(predictions))}
function nums(s){return String(s||"").match(/\d+/g)||[]}
function resultNums(s){return nums(s).slice(0,3)}
function top3Hit(horse,res){return !!horse&&resultNums(res).includes(String(horse).replace(/[^0-9]/g,""))}
function predictionId(date,course,race){return `p-${date}-${course}-${Math.round(toNumber(race))}`}
function resultKey(date,course,race){return `${date}-${course}-${Math.round(toNumber(race))}`}
function findJraResult(p){return jraResults.find(r=>resultKey(r.date,r.course,r.race)===String(p.raceKey||resultKey(p.date,p.course,p.race)))||null}
function runnerFor(result,horse){if(!result||!Array.isArray(result.runners))return null;const n=String(horse||"").replace(/[^0-9]/g,"");return result.runners.find(x=>String(x.horseNo)===n)||null}
function payoutFor(result,type,horse){if(!result?.payouts)return 0;const arr=result.payouts[type]||[];const n=String(horse||"").replace(/[^0-9]/g,"");const row=arr.find(x=>String(x.horses||"").split("-")[0]===n);return row?toNumber(row.payout):0}
function comboPayout(result,a,b){if(!result?.payouts?.wide)return 0;const key=[String(a),String(b)].sort((x,y)=>Number(x)-Number(y)).join("-");const row=result.payouts.wide.find(x=>String(x.horses||"")===key);return row?toNumber(row.payout):0}
function roiForPrediction(p){const r=findJraResult(p);const picks=[p.main,p.second,p.third].filter(Boolean);if(!r?.runners?.length||!picks.length)return{single:null,place:null,wide:null};let singleReturn=0,placeReturn=0;for(const h of picks){singleReturn+=payoutFor(r,"win",h);placeReturn+=payoutFor(r,"place",h)}const widePairs=[];for(let i=0;i<picks.length;i++)for(let j=i+1;j<picks.length;j++)widePairs.push([picks[i],picks[j]]);let wideReturn=0;for(const [a,b] of widePairs)wideReturn+=comboPayout(r,a,b);return{single:singleReturn/(picks.length*100)*100,place:placeReturn/(picks.length*100)*100,wide:widePairs.length?wideReturn/(widePairs.length*100)*100:null}}
function roiText(v){return v==null?"-":`${v.toFixed(1)}%`}
function applyResultToPrediction(p,r){return !!r}
function resultForPrediction(p){return findJraResult(p)}
function actualBetRowsForPrediction(p){return data.filter(r=>String(r.date)===p.date&&String(r.course)===p.course&&toNumber(r.race)===toNumber(p.race))}
