async function deletePredictionCloud(id){if(!session||!supabaseClient)return;const{error}=await supabaseClient.from("keiba_predictions").delete().eq("user_id",session.user.id).eq("id",String(id));if(error){console.error(error);setStatus("同期エラー","error")}}
async function applyJraResults(){renderAi()}
async function loadJraResults(){try{const url=new URL("./data/jra-results.json",document.baseURI);url.searchParams.set("v",Date.now());const res=await fetch(url,{cache:"no-store"});if(!res.ok)throw new Error("results fetch failed");const obj=await res.json();jraResults=Array.isArray(obj)?obj:(Array.isArray(obj?.results)?obj.results:[]);jraResultsUpdatedAt=obj?.updatedAt||"";window.KEIBA_JRA_RESULTS_UPDATED_AT=jraResultsUpdatedAt;const el=$("aiResultStatus");if(el)el.textContent=jraResults.length?`JRA公式結果：${jraResults.length}レース / 最終更新 ${jraResultsUpdatedAt||"確認中"}`:"JRA公式結果データはまだありません。GitHub Actionsの結果更新後に自動連携されます。";renderAi()}catch(e){jraResults=[];const el=$("aiResultStatus");if(el)el.textContent="JRA結果データを取得できませんでした。次回の自動更新で再試行します。";console.warn("JRA result data unavailable",e)}}
function predictionMarkerHtml(p,mark,horse){const r=resultForPrediction(p);const x=runnerFor(r,horse);if(!x)return `<span class="predictionResultLine">${mark} ${escapeHtml(horse||"-")}：結果待ち</span>`;const win=payoutFor(r,"win",horse),place=payoutFor(r,"place",horse);return `<span class="predictionResultLine">${mark} ${escapeHtml(horse||"-")}：${escapeHtml(String(x.finish))}着 / ${escapeHtml(String(x.popularity))}人気 / 単勝${x.odds!=null?escapeHtml(String(x.odds)):"-"}倍 / 単勝払戻${win?yen(win):"-"} / 複勝${place?yen(place):"-"}</span>`}
function renderAiStats(){const n=predictions.length,withResult=predictions.filter(resultForPrediction);const marks=[['◎','main'],['○','second'],['▲','third'],['△','fourth'],['☆','fifth']];const hit=key=>withResult.length?`${(withResult.filter(p=>top3Hit(p[key],(resultForPrediction(p)?.runners||[]).sort((a,b)=>toNumber(a.finish)-toNumber(b.finish)).slice(0,3).map(x=>x.horseNo).join('-'))).length/withResult.length*100).toFixed(1)}%`:'-';const buys=predictions.filter(p=>p.status==='BUY'),buyRows=buys.flatMap(actualBetRowsForPrediction);const inv=buyRows.reduce((s,r)=>s+toNumber(r.inv),0),ret=buyRows.reduce((s,r)=>s+toNumber(r.ret),0);const avgRoi=k=>{const a=withResult.map(roiForPrediction).map(x=>x[k]).filter(x=>x!=null);return a.length?(a.reduce((s,x)=>s+x,0)/a.length).toFixed(1)+'%':'-'};$('aiStats').innerHTML=`<div class="aiStat"><span>予想レース</span><b>${n}</b></div><div class="aiStat"><span>結果連携済み</span><b>${withResult.length}</b></div><div class="aiStat"><span>買い</span><b>${buys.length}</b></div><div class="aiStat"><span>見送り</span><b>${predictions.filter(p=>p.status==='SKIP').length}</b></div><div class="aiStat"><span>◎3着以内</span><b>${hit('main')}</b></div><div class="aiStat"><span>○3着以内</span><b>${hit('second')}</b></div><div class="aiStat"><span>▲3着以内</span><b>${hit('third')}</b></div><div class="aiStat"><span>△3着以内</span><b>${hit('fourth')}</b></div><div class="aiStat"><span>☆3着以内</span><b>${hit('fifth')}</b></div><div class="aiStat"><span>実購入収支</span><b>${buyRows.length?sign(ret-inv):'-'}</b></div><div class="aiStat"><span>実購入回収率</span><b>${inv?(ret/inv*100).toFixed(1)+'%':'-'}</b></div><div class="aiStat"><span>仮想単勝ROI</span><b>${avgRoi('single')}</b></div>`}
function statusLabel(s){return s==='BUY'?'買い':s==='SKIP'?'見送り':'保留'}
function renderPredictions(){const el=$("predictionList"),arr=[...predictions].sort((a,b)=>b.date.localeCompare(a.date)||toNumber(b.race)-toNumber(a.race));if(!arr.length){el.innerHTML="<p class='muted'>まだAI予想がありません。ChatGPTで予想した内容を登録してください。</p>";return}el.innerHTML=arr.map(p=>{const r=resultForPrediction(p),roi=roiForPrediction(p),bets=actualBetRowsForPrediction(p),status=statusLabel(p.status);const result=r?`<div class="resultBox predictionResult"><b>JRA公式結果</b>${predictionMarkerHtml(p,"◎",p.main)}${predictionMarkerHtml(p,"○",p.second)}${predictionMarkerHtml(p,"▲",p.third)}${predictionMarkerHtml(p,"△",p.fourth)}${predictionMarkerHtml(p,"☆",p.fifth)}<span class="predictionResultLine">仮想ROI：単勝 ${roiText(roi.single)} / 複勝 ${roiText(roi.place)} / ワイド ${roiText(roi.wide)}</span></div>`:`<div class="muted predictionPending">JRA公式結果の自動連携待ちです。</div>`;const market=p.marketSnapshot||{};return `<div class="prediction"><div class="predictionTop"><b>${escapeHtml(p.date)}　${escapeHtml(p.course)}${p.race}R</b><span class="badge ${p.status==='BUY'?'hit':''}">${status}</span></div><div class="muted predictionMeta">${escapeHtml(p.raceName||'レース情報')} ${escapeHtml(p.surface||'')} ${escapeHtml(p.distance||'')} ${escapeHtml(p.raceCondition||'')} / 予想時刻 ${escapeHtml(p.predictionTime?new Date(p.predictionTime).toLocaleString('ja-JP'):'-')}</div><div class="predictionBadges"><span class="badge main">◎ ${escapeHtml(p.main)||'-'}</span><span class="badge">○ ${escapeHtml(p.second)||'-'}</span><span class="badge">▲ ${escapeHtml(p.third)||'-'}</span><span class="badge">△ ${escapeHtml(p.fourth)||'-'}</span><span class="badge">☆ ${escapeHtml(p.fifth)||'-'}</span></div><div class="muted predictionMarket">予想時市場：単勝 ${escapeHtml(market.winOdds||'-')} / 馬体重 ${escapeHtml(market.weight||'-')} ${escapeHtml(market.weightChange||'')} / 馬場 ${escapeHtml(market.going||'-')}</div>${p.comment?`<p class="predictionComment">${escapeHtml(p.comment)}</p>`:""}${bets.length?`<div class="predictionBetLink">実購入：${bets.length}件 / 投資 ${yen(bets.reduce((s,x)=>s+toNumber(x.inv),0))} / 払戻 ${yen(bets.reduce((s,x)=>s+toNumber(x.ret),0))}</div>`:`<div class="muted predictionBetLink">実購入：なし</div>`}${result}<div class="predictionActions"><button data-editpred="${escapeHtml(p.id)}">編集</button><button data-delpred="${escapeHtml(p.id)}">削除</button></div></div>`}).join("")}
function renderAi(){renderAiStats();renderPredictions()}
function fillPrediction(p){$("pDate").value=p.date;$("pCourse").value=p.course;$("pRace").value=p.race;$("pStatus").value=p.status||'HOLD';$("pMain").value=p.main;$("pSecond").value=p.second;$("pThird").value=p.third;$("pFourth").value=p.fourth;$("pFifth").value=p.fifth;const m=p.marketSnapshot||{};$("pWinOdds").value=m.winOdds||'';$("pWeight").value=m.weight||'';$("pWeightChange").value=m.weightChange||'';$("pGoing").value=m.going||'';$("pWideOdds").value=m.wideOdds||'';$("pComment").value=p.comment;$('savePrediction').dataset.edit=p.id;openAiDetails()}
function clearPredictionForm(){['pMain','pSecond','pThird','pFourth','pFifth','pWinOdds','pWeight','pWeightChange','pGoing','pWideOdds','pComment'].forEach(id=>$(id).value='');$("pDate").value=new Date().toISOString().slice(0,10);$("pCourse").value="阪神";$("pRace").value="";$("pStatus").value="HOLD";delete $("savePrediction").dataset.edit}
function selectedRaceForPrediction(){return (window.KEIBA_SCHEDULE||[]).find(x=>x.course===$("pCourse").value&&toNumber(x.race)===toNumber($("pRace").value))||window.KEIBA_SELECTED_RACE||{}}
function collectPrediction(){const selected=selectedRaceForPrediction(), date=$("pDate").value,course=$("pCourse").value,race=$("pRace").value;return normalizePrediction({id:$("savePrediction").dataset.edit||predictionId(date,course,race),date,course,race,raceKey:resultKey(date,course,race),raceName:selected.raceName||"",raceCondition:selected.raceCondition||"",distance:selected.distance||"",surface:selected.surface||"",fieldSize:selected.fieldSize||0,going:$("pGoing").value,main:$("pMain").value,second:$("pSecond").value,third:$("pThird").value,fourth:$("pFourth").value,fifth:$("pFifth").value,status:$("pStatus").value,predictionTime:$("savePrediction").dataset.edit?(predictions.find(x=>x.id===$("savePrediction").dataset.edit)?.predictionTime||new Date().toISOString()):new Date().toISOString(),marketSnapshot:{winOdds:$("pWinOdds").value.trim(),wideOdds:$("pWideOdds").value.trim(),weight:$("pWeight").value.trim(),weightChange:$("pWeightChange").value.trim(),going:$("pGoing").value.trim()},comment:$("pComment").value},0)}
async function savePrediction(){const p=collectPrediction();if(!p.date||!p.course||!p.race||!p.main)return alert('日付・競馬場・R・◎本命は入力してください。');const i=predictions.findIndex(x=>x.id===p.id);if(i>=0)predictions[i]=p;else predictions.push(p);savePredictions();renderAi();clearPredictionForm();await upsertPredictionCloud(p)}
function normalizePredictionLine(line){let cleaned=line.trim().replace(/^[-*•]\s*/, '').replace(/^KEIBA_NOTE\s*:\s*/i,'').trim();if(!cleaned)return null;const parts=cleaned.split('|').map(x=>x.trim());if(parts.length<6)return null;let date=parts[0].replace(/\D/g,'');if(/^\d{8}$/.test(date))date=`${date.slice(0,4)}-${date.slice(4,6)}-${date.slice(6,8)}`;if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return null;const course=parts[1],race=toNumber(parts[2]),main=parts[3],second=parts[4],third=parts[5],fourth=parts[6]||'',fifth=parts[7]||'',status=['BUY','HOLD','SKIP'].includes((parts[8]||'').toUpperCase())?(parts[8]||'').toUpperCase():'HOLD',comment=parts.slice(9).join('|');if(!course||race<1||race>12||!main)return null;return normalizePrediction({id:predictionId(date,course,race),date,course,race,main,second,third,fourth,fifth,status,comment},0)}
async function parseAiPaste(){const raw=$("aiPasteText").value.trim();if(!raw){alert("AI予想を貼り付けてください。");return}const lines=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const imported=[],errors=[];lines.forEach((line,i)=>{const pred=normalizePredictionLine(line);if(pred)imported.push(pred);else errors.push(i+1)});if(!imported.length){alert("読み込める予想がありません。\n形式：KEIBA NOTE: 20260919|中山|1|7|11|5");return}const map=new Map(predictions.map(p=>[String(p.id),p]));imported.forEach(pred=>map.set(String(pred.id),pred));predictions=[...map.values()];savePredictions();renderAi();if(session&&supabaseClient){try{const{error}=await supabaseClient.from("keiba_predictions").upsert(imported.map(pred=>predictionCloudRow(pred,session.user.id)),{onConflict:"user_id,id"});if(error)throw error;setStatus("同期済み","ok")}catch(err){console.error(err);setStatus("同期エラー","error");alert(`端末には登録しましたが、クラウド保存に失敗しました。\n${err.message}`)}}$("aiPasteModal").classList.add("hide");$("aiPasteText").value="";alert(`${imported.length}レースのAI予想を登録しました。${errors.length?`\n読み込めなかった行：${errors.join(", ")}行目`:""}`)}
function openAiDetails(){$("aiDetails").classList.remove("hide");$("toggleAi").textContent="詳細を隠す"}
function closeAiDetails(){$("aiDetails").classList.add("hide");$("toggleAi").textContent="詳細を表示"}
$("toggleAi").onclick=()=>$("aiDetails").classList.contains("hide")?openAiDetails():closeAiDetails();
$("savePrediction").onclick=savePrediction;$("clearPredictionForm").onclick=clearPredictionForm;$("openAiPaste").onclick=()=>$('aiPasteModal').classList.remove("hide");$("closeAiPaste").onclick=()=>$('aiPasteModal').classList.add("hide");$("aiPasteModal").onclick=e=>{if(e.target.id==="aiPasteModal")$("aiPasteModal").classList.add("hide")};$("importAiPaste").onclick=parseAiPaste;
$("predictionList").onclick=async e=>{const b=e.target.closest("button");if(!b)return;const id=b.dataset.editpred||b.dataset.delpred;if(b.dataset.editpred){const pred=predictions.find(x=>x.id===id);if(pred)fillPrediction(pred)}else if(b.dataset.delpred&&confirm("このAI予想を削除しますか？")){predictions=predictions.filter(x=>x.id!==id);savePredictions();renderAi();await deletePredictionCloud(id)}};
$("menuToggle").onclick=()=>{$("sideMenu").classList.add("open");$("menuBackdrop").classList.add("open")};$("menuClose").onclick=()=>{$("sideMenu").classList.remove("open");$("menuBackdrop").classList.remove("open")};$("menuBackdrop").onclick=()=>{$("sideMenu").classList.remove("open");$("menuBackdrop").classList.remove("open")};document.querySelectorAll("#sideMenu a").forEach(a=>a.onclick=()=>{$("sideMenu").classList.remove("open");$("menuBackdrop").classList.remove("open")});$("menuHistoryLink").onclick=e=>{e.preventDefault();closeHistory();openHistory()};
clearPredictionForm();loadRaceDates();predictions=loadPredictions();renderAi();closeAiDetails();resetBetRows();loadJraResults().then(()=>initCloud());const chartPanel=$("chartPanel");const chartObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){draw(true)}},{threshold:.2});chartObserver.observe(chartPanel);render();
